"""Build the SFT mixture for the knowledge-injection arm.

Two parts:
  * `data/sft_paper8.jsonl` - the 205k general-instruction samples that produced the
    behaviour gains in docs/EXPERIMENTS.md §4c (the arms there use this alone).
  * `data/cot/shard*.jsonl` - teacher-written MCQ/study-note data generated by
    `scripts/gen_teacher_cot.py` from fineweb-edu passages (knowledge, in the
    teacher's own words; no eval item is ever shown to the teacher).

`--repeat-cot` oversamples the CoT part so a small amount of generated text can
carry weight against 125M tokens of instruction data:

    python scripts/build_sft_cot_mix.py --out data/sft_cot_mix.jsonl --repeat-cot 1
"""
from __future__ import annotations

import argparse
import glob
import json
import os


def count_lines(path: str) -> int:
    with open(path, "rb") as f:
        return sum(1 for _ in f)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--base", default="data/sft_paper8.jsonl")
    ap.add_argument("--cot-glob", default="data/cot/shard*.jsonl")
    ap.add_argument("--out", default="data/sft_cot_mix.jsonl")
    ap.add_argument("--repeat-cot", type=int, default=1)
    ap.add_argument("--chars-per-token", type=float, default=4.0)
    args = ap.parse_args()

    cot_files = sorted(glob.glob(args.cot_glob))
    if not cot_files:
        raise SystemExit(f"no COT shards matched {args.cot_glob}")

    def chars(files):
        return sum(os.path.getsize(f) for f in files)

    n_base = count_lines(args.base)
    n_cot = sum(count_lines(f) for f in cot_files)
    tok_base = chars([args.base]) / args.chars_per_token
    tok_cot = chars(cot_files) / args.chars_per_token
    if n_base == 0 or n_cot == 0:
        raise SystemExit(f"empty input: base={n_base} cot={n_cot}")

    with open(args.out, "w") as fout:
        with open(args.base) as f:
            n_written = 0
            for line in f:
                if line.strip():
                    fout.write(line if line.endswith("\n") else line + "\n")
                    n_written += 1
        for rep in range(args.repeat_cot):
            for path in cot_files:
                with open(path) as f:
                    for line in f:
                        if line.strip():
                            fout.write(line if line.endswith("\n") else line + "\n")
                            n_written += 1
            print(f"[mix] cot pass {rep + 1}/{args.repeat_cot} done", flush=True)

    total_tok = tok_base + tok_cot * args.repeat_cot
    print(f"[mix] base {n_base} samples (~{tok_base / 1e6:.1f}M tok)  "
          f"cot {n_cot} samples x{args.repeat_cot} (~{tok_cot * args.repeat_cot / 1e6:.1f}M tok)")
    print(f"[mix] wrote {n_written} samples (~{total_tok / 1e6:.1f}M tok) -> {args.out}")
    print(f"[mix] cot share of tokens: {tok_cot * args.repeat_cot / total_tok * 100:.1f}%")
    print(f"[mix] steps for 1 epoch at 64 samples/step: {n_written // 64}")


if __name__ == "__main__":
    main()
